function healthProfile(){
  const editable=canEditHealthContext(state);
  const privacy='<p class="muted">Guardado apenas neste navegador. A exportação inclui esta preferência. Ao apagar a preferência atual, os motivos das decisões anteriores permanecem no histórico e nas cópias já exportadas.</p>';
  if(!editable){shell(`${header('STRATEGOS')}<section class="stack" lang="pt-PT"><h2>Há uma prática em curso.</h2><p>Encerra-a antes de alterar as preferências de movimento.</p>${button('Voltar','cancel-health-profile',true)}</section>`);return;}
  if(healthDraft===null){
    shell(`${header('STRATEGOS')}<section class="stack health-context-flow" lang="pt-PT"><p class="eyebrow">CONTEXTO OPCIONAL</p><h2>Há práticas de movimento que queres evitar?</h2><p>A tua escolha limita as práticas propostas. Não interpreta sintomas nem substitui orientações clínicas.</p>${Object.entries(MOVEMENT_PREFERENCES).map(([value,label])=>`<button class="action secondary" data-action="choose-health-preference" data-value="${value}">${esc(label)}</button>`).join('')}${privacy}${button('Agora não','cancel-health-profile',true)}</section>`);return;
  }
  shell(`${header('STRATEGOS')}<section class="stack health-context-flow" lang="pt-PT"><p class="eyebrow">CONFIRMAR A TUA ESCOLHA</p><h2>${esc(MOVEMENT_PREFERENCES[healthDraft])}</h2><p>Esta escolha mantém-se até a alterares ou apagares. Não indicar uma limitação não significa que as práticas sejam clinicamente adequadas.</p>${privacy}${button('Guardar e usar neste dispositivo','save-health-profile')}${button('Cancelar','cancel-health-profile',true)}</section>`);
}
